entries[42416] = { ["name"] = "Glyph of Smite", ["text"] = "Major Glyph\nClasses: Priest\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nYour Smite spell inflicts an additional 20% damage against targets afflicted by [ Solace and Insanity : Power Word: Solace / Holy Fire], but that additional damage does not get transferred by Atonement.\nSell Price:" }
entries[42417] = { ["name"] = "Glyph of Prayer of Mending", ["text"] = "Major Glyph\nClasses: Priest\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nThe first charge of your Prayer of Mending heals for an additional 60% but your Prayer of Mending has 1 fewer charge.\nSell Price:" }
entries[42418] = { ["name"] = "Figurine - Emerald Boar", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 84 Attack Power\n\nYellow Socket\nBlue Socket\nSocket Bonus: + 12 Attack Power\nRequires Level 75\nRequires Jewelcrafting (400)\nUse: Summons a Phantom Boar to fight for you for 30 seconds. (5 Min Cooldown)\nSell Price:" }
