entries[42749] = { ["name"] = "Glyph of Mana Gem", ["text"] = "Major Glyph\nClasses: Mage\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nYour Conjure Mana Gem spell now creates a Brilliant Mana Gem, which holds up to 10 charges.\nSell Price:" }
