entries[42897] = { ["name"] = "Glyph of Aspects", ["text"] = "Minor Glyph\nClasses: Hunter\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nEach time you activate a new Aspect, an animal companion representing that Aspect will follow you for 15 sec.\nSell Price:" }
entries[42898] = { ["name"] = "Glyph of Camouflage", ["text"] = "Major Glyph\nClasses: Hunter\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nYour Camouflage ability now provides stealth even while moving, but your movement speed while Camouflage is active is reduced by 50%.\nSell Price:" }
entries[42899] = { ["name"] = "Glyph of Liberation", ["text"] = "Major Glyph\nClasses: Hunter\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nWhen you Disengage, you are healed for 5% of your total health.\nSell Price:" }
entries[42900] = { ["name"] = "Glyph of Mending", ["text"] = "Major Glyph\nClasses: Hunter\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nYour Mend Pet now heals every 1 sec, and heals for an additional 25% of your pet's health over its duration.\nSell Price:" }
entries[42901] = { ["name"] = "Glyph of Distracting Shot", ["text"] = "Major Glyph\nClasses: Hunter\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nYour Distracting Shot now distracts the target to attack your pet instead of you.\nSell Price:" }
entries[42902] = { ["name"] = "Glyph of Endless Wrath", ["text"] = "Major Glyph\nClasses: Hunter\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nWhile Bestial Wrath is active, your pet cannot be killed, but can still be damaged.\nSell Price:" }
entries[42903] = { ["name"] = "Glyph of Deterrence", ["text"] = "Major Glyph\nClasses: Hunter\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nIncreases the damage reduction granted by Deterrence by 20%.\nSell Price:" }
entries[42904] = { ["name"] = "Glyph of Disengage", ["text"] = "Major Glyph\nClasses: Hunter\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nIncreases the distance you travel when you Disengage.\nSell Price:" }
entries[42905] = { ["name"] = "Glyph of Freezing Trap", ["text"] = "Major Glyph\nClasses: Hunter\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nWhen your Freezing Trap breaks, the victim's movement speed is reduced by 70% for 4 sec.\nSell Price:" }
entries[42906] = { ["name"] = "Glyph of Ice Trap", ["text"] = "Major Glyph\nClasses: Hunter\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nIncreases the radius of the effect from your Ice Trap by 2 yards.\nSell Price:" }
entries[42907] = { ["name"] = "Glyph of Misdirection", ["text"] = "Major Glyph\nClasses: Hunter\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nWhen you use Misdirection on your pet, the cooldown on your Misdirection is reset.\nSell Price:" }
entries[42908] = { ["name"] = "Glyph of Explosive Trap", ["text"] = "Major Glyph\nClasses: Hunter\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nYour Explosive Trap no longer deals damage, instead knocking enemies back from the trap when it explodes.\nSell Price:" }
entries[42909] = { ["name"] = "Glyph of Animal Bond", ["text"] = "Major Glyph\nClasses: Hunter\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nWhile your pet is active, all healing done to you and your pet is increased by 10%.\nSell Price:" }
entries[42910] = { ["name"] = "Glyph of No Escape", ["text"] = "Major Glyph\nClasses: Hunter\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nIncreases the ranged critical strike chance of all of your attacks on targets affected by your Freezing Trap by 100%.\nSell Price:" }
entries[42911] = { ["name"] = "Glyph of Pathfinding", ["text"] = "Major Glyph\nClasses: Hunter\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nIncreases the speed bonus of your Aspect of the Cheetah and Aspect of the Pack by 8%, and increases your speed while mounted by 10%. The mounted movement speed increase does not stack with other effects.\nSell Price:" }
entries[42912] = { ["name"] = "Glyph of Tame Beast", ["text"] = "Minor Glyph\nClasses: Hunter\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nReduces the time required to complete Tame Beast by 4 sec.\nSell Price:" }
entries[42913] = { ["name"] = "Glyph of Snake Trap", ["text"] = "Major Glyph\nClasses: Hunter\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nSnakes from your Snake Trap take 90% reduced damage from area of effect attacks.\nSell Price:" }
entries[42914] = { ["name"] = "Glyph of Aimed Shot", ["text"] = "Major Glyph\nClasses: Hunter\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nYour Aimed Shot can now be used while moving.\nSell Price:" }
entries[42915] = { ["name"] = "Glyph of Mend Pet", ["text"] = "Major Glyph\nClasses: Hunter\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nGives your Mend Pet ability a 100% chance of cleansing 1 Curse, Disease, Magic or Poison effect from your pet each tick.\nSell Price:" }
